                        end
                        if chestPos then
                            _tp(chestPos)
                            repeat wait() until not chest.Parent or chest:GetAttribute("IsDisabled") or not _G.ChestFarmingHOP
                        end
                        break 
                    end
                end
                if not chestFound and _G.ChestFarmingHOP then
                    wait(1)
                    Hop()
                end
            end
        end)
