function DetectEgg()
	local V, y, P = t.Character.PrimaryPart.Position, 1 / 0
	for Y, H in pairs(game:GetService("CollectionService"):GetTagged("EasterEgg26")) do
		Y = (V - H:GetAttribute("CFrame").Position).Magnitude
		if Y < y then
			y, P = Y, H
		end
	end
	return P
end
