				if not R then
					R = (tick())
				elseif tick() - R >= 5 then
					Instance.new("IntValue", g).Name = "Ignored"
					wait(0.5)
				end
				game:GetService("VirtualInputManager"):SendKeyEvent(true, "Space", false, game)
				wait()
