			end
			toTarget(g.CFrame, true)
		until not g
			or not g.Parent
			or not Settings["Auto Upgrade Race V2-V3"]
			or (g:GetAttribute("IsDisabled"))
			or (g:FindFirstChild("Ignored"))
			or not g:FindFirstChild("TouchInterest")
