function DetectMobCDK()
	for g, g in pairs(game.Workspace.Enemies:GetChildren()) do
		if
			g:IsA("Model")
			and (g:FindFirstChild("Humanoid"))
			and g.Humanoid.Health > 0
			and t:DistanceFromCharacter(g.HumanoidRootPart.Position) < 300
		then
			return g
		end
	end
