            function Hop()
                local IhnjzKwVVcT = game.PlaceId
                local okNreFyGH = {}
                local TPqVCoXUcEBw = ""
                local tmhCeoiMEDBD = os.date("!*t").hour
                local soEUdQkaBM = false
                function TPReturner()
                    local mYieEVJrDqJ
                    if TPqVCoXUcEBw ~= "" then
                        mYieEVJrDqJ = game.HttpService:JSONDecode(
                            game:HttpGet(
                                "https://games.roblox.com/v1/games/"
                                    .. IhnjzKwVVcT
                                    .. "/servers/Public?sortOrder=Asc&limit=100&cursor="
                                    .. TPqVCoXUcEBw
                            )
                        )
                    else
                        mYieEVJrDqJ = game.HttpService:JSONDecode(
                            game:HttpGet(
                                "https://games.roblox.com/v1/games/"
                                    .. IhnjzKwVVcT
                                    .. "/servers/Public?sortOrder=Asc&limit=100"
                            )
                        )
                    end
                    local iNyKjIlsCsrX = ""
                    if
                        mYieEVJrDqJ.nextPageCursor
                        and mYieEVJrDqJ.nextPageCursor ~= "null"
                        and mYieEVJrDqJ.nextPageCursor ~= "null"
                    then
                        TPqVCoXUcEBw = mYieEVJrDqJ.nextPageCursor
                    end
                    local AImCRZGsH = 0
                    for soEUdQkaBM, hNiYoyDPjz in pairs(mYieEVJrDqJ.data) do
                        local pRdsZFoIsB = true
                        iNyKjIlsCsrX = tostring(hNiYoyDPjz.id)
                        if tonumber(hNiYoyDPjz.maxPlayers) > tonumber(hNiYoyDPjz.playing) then
                            for soEUdQkaBM, v12 in pairs(okNreFyGH) do
                                if AImCRZGsH ~= 0 then
                                    if iNyKjIlsCsrX == tostring(v12) then
                                        pRdsZFoIsB = false
                                    end
                                elseif tonumber(tmhCeoiMEDBD) ~= tonumber(v12) then
                                    local soEUdQkaBM = pcall(function()
                                        okNreFyGH = {}
                                        table.insert(okNreFyGH, tmhCeoiMEDBD)
                                    end)
                                end
                                AImCRZGsH = AImCRZGsH + 1
                            end
                            if pRdsZFoIsB == true then
                                table.insert(okNreFyGH, iNyKjIlsCsrX)
                                GmMeXykNf(0.1)
                                pcall(function()
                                    GmMeXykNf()
                                    game:GetService("TeleportService")
                                        :TeleportToPlaceInstance(IhnjzKwVVcT, iNyKjIlsCsrX, game.Players.LocalPlayer)
                                end)
                                GmMeXykNf(0.1)
                            end
                        end
                    end
