local launchButtons={}
local function rebrand(id, source)
    -- UI names only. This does not modify the original logic or delete features.
    if id == "custom" then
        source = source:gsub("Redz Hub %[ BETA ACCESS %] : Blox Fruit", "andepzai | Blox Fruits")
        source = source:gsub("SaveFolder = \"XoshiroXzKHub\"", "SaveFolder = \"andepzai_Custom\"")
    elseif id == "banana" then
        source = source:gsub('FolderName = "Banana Cat Hub"','FolderName = "andepzai_Banana"')
        source = source:gsub('Title = "Blox Fruit", Desc = " %- Blox Fruit"','Title = "andepzai", Desc = "Blox Fruits"')
    end
    return source
end
local function launch(id)
    if State.launching or State.loaded then
        log("Đã kích hoạt "..tostring(State.active or "một bộ")..". Hãy vào phiên mới nếu muốn đổi bản.",C.Red)
        return
    end
    if type(loadstring) ~= "function" then
        log("Executor chưa hỗ trợ loadstring; không thể khởi chạy.",C.Red)
        return
    end
    if not game:IsLoaded() then log("Đang đợi trò chơi tải...",C.Dim) end
    State.launching=true
    State.active=id
    log("Đang chuẩn bị "..Metadata[id].title.."...",C.Accent)
    for _,b in pairs(launchButtons) do b.Text="ĐANG CHUẨN BỊ" end
    task.spawn(function()
        local started=os.clock()
        while not game:IsLoaded() and os.clock()-started<35 do task.wait(0.2) end
        if not game:IsLoaded() then
            State.lastError="Game:IsLoaded() timeout"
            log("Game chưa tải xong trong thời hạn.",C.Red)
            State.launching=false
            return
        end
        local src = rebrand(id, Sources[id])
        local ok,compiled,compileErr=pcall(function()
            return loadstring(src, "@andepzai/"..id)
        end)
        if not ok or type(compiled)~="function" then
            local ok2,result,err2=pcall(function() return loadstring(src) end)
            if not ok2 or type(result)~="function" then
                State.lastError=tostring(err2 or result or compileErr or compiled)
                log("Lỗi biên dịch "..id..": "..State.lastError,C.Red)
                State.launching=false
                return
            end
            compiled=result
        end
        State.loaded=true
        State.launching=false
        log("Đã gọi bộ "..Metadata[id].title..". Kiểm tra cửa sổ chức năng của bộ này.",C.Green)
        task.spawn(function()
            local worked,err=pcall(compiled)
            if not worked then
                State.lastError=tostring(err)
                log("Bộ "..Metadata[id].title.." báo lỗi: "..State.lastError,C.Red)
                warn("[andepzai] "..State.lastError)
            else
                log("Đã kết thúc tác vụ khởi chạy "..Metadata[id].title..".",C.Green)
            end
        end)
    end)
end
