local function updateStatus()
    local ch=Player.Character
    local hum=ch and ch:FindFirstChildOfClass("Humanoid")
    local level=Player:FindFirstChild("Data") and Player.Data:FindFirstChild("Level")
    local sea="Không xác định"
    if game.PlaceId==2753915549 or game.PlaceId==85211729168715 then sea="Sea 1"
    elseif game.PlaceId==4442272183 or game.PlaceId==79091703265657 then sea="Sea 2"
    elseif game.PlaceId==7449423635 or game.PlaceId==100117331123089 then sea="Sea 3" end
    local fields={
        "TÀI KHOẢN: "..Player.Name,
        "USER ID: "..tostring(Player.UserId),
        "LEVEL: "..(level and tostring(level.Value) or "Đang tải"),
        "THẾ GIỚI: "..sea,
        "MÁU: "..(hum and string.format("%.0f / %.0f",hum.Health,hum.MaxHealth) or "Chưa có nhân vật"),
        "PLACE ID: "..tostring(game.PlaceId),
        "JOB ID: "..tostring(game.JobId):sub(1,28),
        "BỘ ĐÃ CHỌN: "..(State.active and Metadata[State.active].title or "Chưa có"),
    }
    statusDetails.Text=table.concat(fields,"\n")
end
