    local fx=button(t,"GIẢM HIỆU ỨNG: TẮT",UDim2.fromOffset(7,146),UDim2.new(1,-20,0,42),C.Panel,C.Purple)
    fx.Activated:Connect(function()
        if not effectsOn then
            effects={}
            for _,e in ipairs(Lighting:GetChildren()) do
                if e:IsA("PostEffect") then
                    effects[e]=e.Enabled
                    e.Enabled=false
                end
            end
            effectsOn=true
            fx.Text="GIẢM HIỆU ỨNG: BẬT"
            log("Đã tắt hiệu ứng hậu xử lý trong Lighting.",C.Green)
        else
            for e,prev in pairs(effects) do
                if e and e.Parent then e.Enabled=prev end
            end
            effects={}
            effectsOn=false
            fx.Text="GIẢM HIỆU ỨNG: TẮT"
            log("Đã khôi phục hiệu ứng ban đầu.",C.Dim)
