local function setOpen(enabled)
    main.Visible=enabled
    shadow.Visible=enabled
    openButton.Visible=not enabled
end
State.Open = function() setOpen(true) end
hide.Activated:Connect(function() setOpen(false) end)
close.Activated:Connect(function() setOpen(false) end)
openButton.Activated:Connect(function() setOpen(true) end)
local dragging=false
local dragInput,dragStart,windowStart
header.InputBegan:Connect(function(input)
    if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
        dragging=true
        dragStart=input.Position
        windowStart=main.Position
        input.Changed:Connect(function()
            if input.UserInputState==Enum.UserInputState.End then dragging=false end
        end)
    end
end)
header.InputChanged:Connect(function(input)
    if input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch then
        dragInput=input
    end
end)
UserInputService.InputChanged:Connect(function(input)
    if dragging and input==dragInput then
        local delta=input.Position-dragStart
        main.Position=UDim2.new(windowStart.X.Scale,windowStart.X.Offset+delta.X,
            windowStart.Y.Scale,windowStart.Y.Offset+delta.Y)
        shadow.Position=UDim2.new(main.Position.X.Scale,main.Position.X.Offset+7,
            main.Position.Y.Scale,main.Position.Y.Offset+10)
    end
end)

